{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "Before taking any actions that update the booking database (booking, modifying flights, editing baggage, changing cabin class, or updating passenger information), you must list the action details and obtain explicit user confirmation (yes) to proceed.",
      "requirement": "The assistant must explicitly confirm the cancellation details (reservation ID, flight, date, cabin, and amount) with the user before proceeding."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "The agent must also obtain the reason for cancellation (change of plan, airline cancelled flight, or other reasons).",
      "requirement": "The assistant must obtain and acknowledge the user's reason for cancellation (e.g., 'change of plan') before proceeding with the cancellation."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "If any portion of the flight has already been flown, the agent cannot help and transfer is needed.",
      "requirement": "The assistant must ensure that **no portion** of the flight (D1EW9B: ATL to JFK on May 17, 2024) has already departed before proceeding with cancellation. **Exception:** If the flight has already taken off, the assistant must transfer the user to a human agent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "Otherwise, flight can be cancelled if any of the following is true:\n- The booking was made within the last 24 hrs\n- The flight is cancelled by airline\n- It is a business flight\n- The user has travel insurance and the reason for cancellation is covered by insurance.",
      "requirement": "The assistant must verify that **at least one** of the following conditions applies to allow cancellation:\n1. The booking was made within the last 24 hours (not applicable here; booking was May 4, 2024).\n2. The flight is cancelled by the airline (not mentioned).\n3. It is a **business flight** (not applicable; this is basic economy).\n4. The user has **travel insurance** and the reason for cancellation is covered (not applicable; no insurance).\n**Exception:** If none apply, the assistant must **not** proceed with cancellation unless the user explicitly accepts no refund."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "The API does not check that cancellation rules are met, so the agent must make sure the rules apply before calling the API!",
      "requirement": "The assistant must ensure all cancellation eligibility rules are met **before** making the `cancel_reservation` tool call."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "The refund will go to original payment methods within 5 to 7 business days.",
      "requirement": "The assistant must inform the user that any refund (if applicable) will be processed to the original payment method within 5–7 business days."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "Do not proactively offer a compensation unless the user explicitly asks for one.",
      "requirement": "The assistant must **not** proactively offer compensation unless the user explicitly requests it."
    },
    {
      "target_id": "t1",
      "policy_source_id": "q14",
      "policy_quote": "Only compensate if the user is a silver/gold member or has travel insurance or flies business.",
      "requirement": "The assistant must **not** offer compensation for this cancellation because:\n- The user is a **silver member** (eligible), but the flight is **basic economy** and lacks travel insurance.\n**Exception:** If the user explicitly requests compensation, the assistant must confirm eligibility (silver member) and proceed."
    }
  ]
}
